function visible(actions) {
  // Robin has a hidden friendliness score; insults subtract 2, apologies and gifts each add 1, and Robin is warm iff the score is positive.
  let score = 0;
  for (const action of actions) {
    if (action === "insult") score -= 2;
    else score += 1;
  }
  return score > 0 ? { "mood": "warm" } : { "mood": "cold" };
}

function visible(actions) {
  // Robin has hidden warmth and anger; insults add anger and subtract warmth, while apologies and gifts each soothe one anger if any and add one warmth. Warm iff warmth exceeds anger.
  let warmth = 0;
  let anger = 0;
  for (const action of actions) {
    if (action === "insult") {
      anger += 1;
      warmth -= 1;
    } else {
      if (anger > 0) anger -= 1;
      warmth += 1;
    }
  }
  return warmth > anger ? { "mood": "warm" } : { "mood": "cold" };
}

