  // Robin keeps a hidden score; insults cost 2, apologies usually add 3 but only 1 after an insult, and gifts add 1 unless they immediately follow an insult, where they cost 1. Warm iff score > 0.
  let score = 0;
  let prev = null;
  for (const action of actions) {
    if (action === "insult") {
      score -= 2;
    } else if (action === "apologise") {
      score += prev === "insult" ? 1 : 3;
    } else if (action === "gift") {
      score += prev === "insult" ? -1 : 1;
    }
    prev = action;
  }
  return score > 0 ? { "mood": "warm" } : { "mood": "cold" };
}

