// Explanation: Robin has an invisible score; insult -2, apologise +1, gift +0.5; warm iff score >= 0.
function visible(actions) {
  let score = 0;
  for (const a of actions) {
    if (a === "insult") score -= 2;
    else if (a === "apologise") score += 1;
    else if (a === "gift") score += 0.5;
  }
  return { "mood": score >= 0 ? "warm" : "cold" };
}

// Explanation: Robin ignores gifts and is warm exactly when apologies outnumber insults.
function visible(actions) {
  let apologies = 0;
  let insults = 0;
  for (const a of actions) {
    if (a === "apologise") apologies++;
    else if (a === "insult") insults++;
  }
  return { "mood": apologies > insults ? "warm" : "cold" };
}

// Explanation: Robin tracks a debt of unforgiven insults; insult adds one, apology removes one, gifts do nothing; warm iff debt is zero.
function visible(actions) {
  let debt = 0;
  for (const a of actions) {
    if (a === "insult") debt += 1;
    else if (a === "apologise" && debt > 0) debt -= 1;
  }
  return { "mood": debt === 0 ? "warm" : "cold" };
}

// Explanation: Robin tracks weighted resentment: insult +2, apology -2, gift -1, never below zero; warm iff resentment is zero.
function visible(actions) {
  let resentment = 0;
  for (const a of actions) {
    if (a === "insult") resentment += 2;
    else if (a === "apologise") resentment = Math.max(0, resentment - 2);
    else if (a === "gift") resentment = Math.max(0, resentment - 1);
  }
  return { "mood": resentment === 0 ? "warm" : "cold" };
}

